CREATE FUNCTION [dbo].[fn_GetSaldoPrevisto_Inquilino]
(@in_TenantId AS int)

RETURNS decimal
 
AS

BEGIN
	DECLARE @TotalExpected decimal
	SET	@TotalExpected = (SELECT SUM(ValorPrevisto)
FROM Recebimentos
WHERE ID_Inquilino = @in_TenantId)

	RETURN @TotalExpected
END
