         [IRSAnual], [Vencimento], [Notas], [NIF], [Identificacao], [Titular], [ValidadeCC], [DataNascimento], [Ativo])
    VALUES
        (@Nome, @Morada, @Naturalidade, @ID_EstadoCivil, @Contacto1, @Contacto2, @eMail,
         @IRSAnual, @Vencimento, @Notas, @NIF, @Identificacao, @Titular, @ValidadeCC, @DataNascimento, @Ativo);
    SELECT CAST(SCOPE_IDENTITY() AS int);
END;
