CREATE   PROCEDURE [dbo].[usp_Notifications_PurgeOld]
    @RetentionDays int = 180
AS
BEGIN
    SET NOCOUNT ON;
    DELETE FROM [dbo].[Notifications]
    WHERE [CreatedAt] < DATEADD(day, -@RetentionDays, SYSDATETIME()) AND [ReadAt] IS NOT NULL;
    SELECT @@ROWCOUNT;
END
